CREATE TABLE IF NOT EXISTS "PROFESORES" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "PERSONA_ID" BIGINT NOT NULL UNIQUE,
    "CODIGO" VARCHAR(30) NOT NULL UNIQUE,
    "ESPECIALIDAD" VARCHAR(120) NOT NULL,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT "FK_PROFESORES_PERSONAS" FOREIGN KEY ("PERSONA_ID") REFERENCES "PERSONAS" ("ID")
);

CREATE TABLE IF NOT EXISTS "ASIGNATURAS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CODIGO" VARCHAR(30) NOT NULL UNIQUE,
    "NOMBRE" VARCHAR(120) NOT NULL,
    "AREA" VARCHAR(120) NOT NULL,
    "COLOR_HEX" VARCHAR(7) NOT NULL,
    "ACTIVA" BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS "CURSOS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CODIGO" VARCHAR(30) NOT NULL UNIQUE,
    "NOMBRE" VARCHAR(120) NOT NULL,
    "NIVEL" VARCHAR(40) NOT NULL,
    "LETRA" VARCHAR(5) NOT NULL,
    "ANIO_ESCOLAR" INTEGER NOT NULL,
    "JORNADA" VARCHAR(30) NOT NULL,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS "BLOQUES_HORARIOS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "DIA_SEMANA" VARCHAR(15) NOT NULL,
    "HORA_INICIO" TIME NOT NULL,
    "HORA_FIN" TIME NOT NULL,
    "ORDEN" INTEGER NOT NULL,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT "UK_BLOQUES_HORARIOS" UNIQUE ("DIA_SEMANA", "ORDEN")
);

CREATE TABLE IF NOT EXISTS "CARGAS_DOCENTES" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "PROFESOR_ID" BIGINT NOT NULL,
    "CURSO_ID" BIGINT NOT NULL,
    "ASIGNATURA_ID" BIGINT NOT NULL,
    "ANIO_ESCOLAR" INTEGER NOT NULL,
    "HORAS_SEMANALES" INTEGER NOT NULL,
    "ES_PROFESOR_JEFE" BOOLEAN NOT NULL DEFAULT FALSE,
    "ACTIVA" BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT "FK_CARGAS_DOCENTES_PROFESORES" FOREIGN KEY ("PROFESOR_ID") REFERENCES "PROFESORES" ("ID"),
    CONSTRAINT "FK_CARGAS_DOCENTES_CURSOS" FOREIGN KEY ("CURSO_ID") REFERENCES "CURSOS" ("ID"),
    CONSTRAINT "FK_CARGAS_DOCENTES_ASIGNATURAS" FOREIGN KEY ("ASIGNATURA_ID") REFERENCES "ASIGNATURAS" ("ID"),
    CONSTRAINT "UK_CARGAS_DOCENTES" UNIQUE ("PROFESOR_ID", "CURSO_ID", "ASIGNATURA_ID", "ANIO_ESCOLAR")
);

CREATE TABLE IF NOT EXISTS "HORARIOS_CARGAS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CARGA_DOCENTE_ID" BIGINT NOT NULL,
    "BLOQUE_HORARIO_ID" BIGINT NOT NULL,
    "SALA" VARCHAR(30),
    CONSTRAINT "FK_HORARIOS_CARGAS_CARGAS_DOCENTES" FOREIGN KEY ("CARGA_DOCENTE_ID") REFERENCES "CARGAS_DOCENTES" ("ID"),
    CONSTRAINT "FK_HORARIOS_CARGAS_BLOQUES_HORARIOS" FOREIGN KEY ("BLOQUE_HORARIO_ID") REFERENCES "BLOQUES_HORARIOS" ("ID"),
    CONSTRAINT "UK_HORARIOS_CARGAS" UNIQUE ("CARGA_DOCENTE_ID", "BLOQUE_HORARIO_ID")
);

CREATE TABLE IF NOT EXISTS "PLANIFICACIONES" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CARGA_DOCENTE_ID" BIGINT NOT NULL,
    "TITULO" VARCHAR(180) NOT NULL,
    "UNIDAD" VARCHAR(120) NOT NULL,
    "OBJETIVO_APRENDIZAJE" VARCHAR(255) NOT NULL,
    "FECHA_CLASE" DATE NOT NULL,
    "ESTADO" VARCHAR(30) NOT NULL,
    "RECURSOS" TEXT,
    "ACTIVIDADES" TEXT,
    "EVALUACION" TEXT,
    "OBSERVACIONES" TEXT,
    "CREADO_EN" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "FK_PLANIFICACIONES_CARGAS_DOCENTES" FOREIGN KEY ("CARGA_DOCENTE_ID") REFERENCES "CARGAS_DOCENTES" ("ID")
);

INSERT INTO "PROFESORES" ("PERSONA_ID", "CODIGO", "ESPECIALIDAD", "ACTIVO")
SELECT p."ID", 'PROF-JP', 'Matematicas y planificacion curricular', TRUE
FROM "PERSONAS" p
WHERE p."RUN" = '11111111-1'
  AND NOT EXISTS (SELECT 1 FROM "PROFESORES" pr WHERE pr."CODIGO" = 'PROF-JP');

INSERT INTO "PROFESORES" ("PERSONA_ID", "CODIGO", "ESPECIALIDAD", "ACTIVO")
SELECT p."ID", 'PROF-MG', 'Lenguaje y comunicacion', TRUE
FROM "PERSONAS" p
WHERE p."RUN" = '22222222-2'
  AND NOT EXISTS (SELECT 1 FROM "PROFESORES" pr WHERE pr."CODIGO" = 'PROF-MG');

INSERT INTO "ASIGNATURAS" ("CODIGO", "NOMBRE", "AREA", "COLOR_HEX", "ACTIVA")
SELECT * FROM (
    VALUES
        ('MAT', 'Matematicas', 'Ciencias basicas', '#2F54EB', TRUE),
        ('LEN', 'Lenguaje y comunicacion', 'Humanidades', '#13A8A8', TRUE),
        ('CN', 'Ciencias naturales', 'Ciencias', '#52C41A', TRUE),
        ('HIS', 'Historia y geografia', 'Humanidades', '#FA8C16', TRUE)
) AS v("CODIGO", "NOMBRE", "AREA", "COLOR_HEX", "ACTIVA")
WHERE NOT EXISTS (
    SELECT 1 FROM "ASIGNATURAS" a WHERE a."CODIGO" = v."CODIGO"
);

INSERT INTO "CURSOS" ("CODIGO", "NOMBRE", "NIVEL", "LETRA", "ANIO_ESCOLAR", "JORNADA", "ACTIVO")
SELECT * FROM (
    VALUES
        ('5B-2026', '5 Basico B', '5 Basico', 'B', 2026, 'Manana', TRUE),
        ('6A-2026', '6 Basico A', '6 Basico', 'A', 2026, 'Manana', TRUE),
        ('7A-2026', '7 Basico A', '7 Basico', 'A', 2026, 'Tarde', TRUE),
        ('8B-2026', '8 Basico B', '8 Basico', 'B', 2026, 'Tarde', TRUE)
) AS v("CODIGO", "NOMBRE", "NIVEL", "LETRA", "ANIO_ESCOLAR", "JORNADA", "ACTIVO")
WHERE NOT EXISTS (
    SELECT 1 FROM "CURSOS" c WHERE c."CODIGO" = v."CODIGO"
