INSERT INTO "BLOQUES_HORARIOS" ("DIA_SEMANA", "HORA_INICIO", "HORA_FIN", "ORDEN", "ACTIVO")
SELECT * FROM (
    VALUES
        ('LUNES', TIME '08:00', TIME '08:45', 1, TRUE),
        ('LUNES', TIME '08:55', TIME '09:40', 2, TRUE),
        ('MARTES', TIME '10:00', TIME '10:45', 3, TRUE),
        ('MIERCOLES', TIME '11:00', TIME '11:45', 4, TRUE),
        ('JUEVES', TIME '12:00', TIME '12:45', 5, TRUE),
        ('VIERNES', TIME '08:00', TIME '08:45', 1, TRUE),
        ('VIERNES', TIME '08:55', TIME '09:40', 2, TRUE)
) AS v("DIA_SEMANA", "HORA_INICIO", "HORA_FIN", "ORDEN", "ACTIVO")
WHERE NOT EXISTS (
    SELECT 1
    FROM "BLOQUES_HORARIOS" b
    WHERE b."DIA_SEMANA" = v."DIA_SEMANA"
      AND b."ORDEN" = v."ORDEN"
);

INSERT INTO "CARGAS_DOCENTES" ("PROFESOR_ID", "CURSO_ID", "ASIGNATURA_ID", "ANIO_ESCOLAR", "HORAS_SEMANALES", "ES_PROFESOR_JEFE", "ACTIVA")
SELECT pr."ID", c."ID", a."ID", 2026, 6, TRUE, TRUE
FROM "PROFESORES" pr, "CURSOS" c, "ASIGNATURAS" a
WHERE pr."CODIGO" = 'PROF-JP'
  AND c."CODIGO" = '5B-2026'
  AND a."CODIGO" = 'MAT'
  AND NOT EXISTS (
      SELECT 1 FROM "CARGAS_DOCENTES" cd
      WHERE cd."PROFESOR_ID" = pr."ID"
        AND cd."CURSO_ID" = c."ID"
        AND cd."ASIGNATURA_ID" = a."ID"
        AND cd."ANIO_ESCOLAR" = 2026
  );

