INSERT INTO "CARGAS_DOCENTES" ("PROFESOR_ID", "CURSO_ID", "ASIGNATURA_ID", "ANIO_ESCOLAR", "HORAS_SEMANALES", "ES_PROFESOR_JEFE", "ACTIVA")
