INSERT INTO "HORARIOS_CARGAS" ("CARGA_DOCENTE_ID", "BLOQUE_HORARIO_ID", "SALA")
SELECT cd."ID", bh."ID", 'SALA-12'
FROM "CARGAS_DOCENTES" cd
JOIN "PROFESORES" pr ON pr."ID" = cd."PROFESOR_ID"
JOIN "CURSOS" c ON c."ID" = cd."CURSO_ID"
JOIN "ASIGNATURAS" a ON a."ID" = cd."ASIGNATURA_ID"
JOIN "BLOQUES_HORARIOS" bh ON bh."DIA_SEMANA" = 'LUNES' AND bh."ORDEN" = 1
WHERE pr."CODIGO" = 'PROF-JP' AND c."CODIGO" = '5B-2026' AND a."CODIGO" = 'MAT'
  AND NOT EXISTS (
      SELECT 1 FROM "HORARIOS_CARGAS" hc
      WHERE hc."CARGA_DOCENTE_ID" = cd."ID" AND hc."BLOQUE_HORARIO_ID" = bh."ID"
  );

INSERT INTO "HORARIOS_CARGAS" ("CARGA_DOCENTE_ID", "BLOQUE_HORARIO_ID", "SALA")
SELECT cd."ID", bh."ID", 'SALA-12'
FROM "CARGAS_DOCENTES" cd
JOIN "PROFESORES" pr ON pr."ID" = cd."PROFESOR_ID"
JOIN "CURSOS" c ON c."ID" = cd."CURSO_ID"
JOIN "ASIGNATURAS" a ON a."ID" = cd."ASIGNATURA_ID"
