INSERT INTO "PLANIFICACIONES" (
    "CARGA_DOCENTE_ID",
    "TITULO",
    "UNIDAD",
    "OBJETIVO_APRENDIZAJE",
    "FECHA_CLASE",
    "ESTADO",
    "RECURSOS",
    "ACTIVIDADES",
    "EVALUACION",
    "OBSERVACIONES"
)
SELECT cd."ID",
       'Resolucion de problemas con multiplicacion',
       'Unidad 1 - Numeros y operaciones',
       'Aplicar estrategias para resolver problemas de multiplicacion en contexto',
       DATE '2026-04-06',
       'PLANIFICADA',
       'Guia impresa, proyector, material concreto',
       'Inicio con desafio mental, desarrollo en parejas y cierre con ticket de salida',
       'Revision de ejercicios y retroalimentacion inmediata',
       'Curso responde bien al trabajo colaborativo'
FROM "CARGAS_DOCENTES" cd
JOIN "PROFESORES" pr ON pr."ID" = cd."PROFESOR_ID"
JOIN "CURSOS" c ON c."ID" = cd."CURSO_ID"
JOIN "ASIGNATURAS" a ON a."ID" = cd."ASIGNATURA_ID"
WHERE pr."CODIGO" = 'PROF-JP' AND c."CODIGO" = '5B-2026' AND a."CODIGO" = 'MAT'
  AND NOT EXISTS (
      SELECT 1 FROM "PLANIFICACIONES" p
      WHERE p."CARGA_DOCENTE_ID" = cd."ID"
        AND p."FECHA_CLASE" = DATE '2026-04-06'
  );

